main_repeat_audit_program:
import pathlib,hashlib,json,re
root=pathlib.Path('/home/sasaki/datasets/openloris/corridor1-1-m8-compact-connectivity-v1')
old=pathlib.Path('/home/sasaki/datasets/openloris/corridor1-1-m8-atlas-landmarks-v1/connected-filtered-ba-v1')
time=(root/'main-repeat.time').read_text();assert 'Exit status: 0' in time
hashes={}
for folder,ref in [('model','component-000'),('pre-ba','pre-ba-000')]:
 for name in ['cameras.txt','images.txt','points3D.txt']:
  p=root/'main-repeat'/folder/name
  assert p.read_bytes()==(old/ref/name).read_bytes(),str(p)
  hashes[folder+'/'+name]=hashlib.sha256(p.read_bytes()).hexdigest()
phases={}
for line in (root/'main-repeat.log').read_text().splitlines():
 if line.startswith(('atlas-window-timing:','atlas-pass-timing:','atlas-inner-timing:')):
  d=dict(re.findall(r'(\w+)=([^ ]+)',line))
  phases[d['phase']]=phases.get(d['phase'],0)+float(d['seconds'])
print(json.dumps({'hashes':hashes,'phase_seconds':phases,'time_log':time}))

